HEALTH = "Nutrition and health statements are general, textbook-level and conservative: a dietitian or health worker must review them before release."
KJ = {"carbohydrate": 17, "protein": 17, "fat": 37}   # kJ per gram used in this pack (flagged for review)
def energy(c, p_, f): return c * KJ["carbohydrate"] + p_ * KJ["protein"] + f * KJ["fat"]
assert energy(60, 20, 10) == 1730 and round(10 * 37 / 1730 * 100, 1) == 21.4 and round(1730 / 4.2) == 412
assert round(3500 / 10000 * 100) == 35 and 2 ** 6 == 64

def mkpack(pid, title, level, exam, ref, desc):
    return Pack(pid, title, level=level, subject="sciences", cursus="secondary", exam=exam, wanted="food-science", programRef=ref, description=desc)

