c = p.chapter("hygiene", "Food hygiene, cooking and preservation", REF4)
lesson(c, "hygiene-safety", "Food hygiene and kitchen safety",
  ["Explain why food hygiene matters", "List personal, food and kitchen hygiene rules", "Describe how germs spread to food", "Apply kitchen safety rules"],
  [("definition", "Food hygiene", "**Food hygiene** means keeping food safe to eat. Germs (**bacteria**, viruses, moulds) on hands, surfaces, flies, dirty water or raw meat can contaminate food and cause **food poisoning** with stomach pain, vomiting and diarrhoea."),
   ("methode", "Rules", "- **Wash hands** with soap and clean water before cooking and after using the toilet or touching raw meat or fish.\n- Keep long hair tied and nails clean; cover cuts.\n- Wash fruit and vegetables.\n- Keep raw and cooked food **separate**; use different knives and boards.\n- Cook food thoroughly and keep it covered; store leftovers safely and heat them well.\n- Use clean (boiled or treated) water."),
   ("methode", "Kitchen safety", "Turn pan handles inwards; keep children away from fire; do not leave cooking unattended; dry hands before touching electrical items; keep knives sharp and cut away from your body; clean up spills; store gas cylinders safely and check for leaks as taught by a qualified person."),
   ("pieges", "Be careful", "- Food left in warm conditions for hours can make people ill even if it smells normal.\n- A cloth used for everything spreads germs.\n- First aid advice must come from a trained person. " + HEALTH)],
  ("Rules", cols("Hygiene: do and do not", ["Do", "Do not"], [["Wash hands", "Cook with dirty hands"], ["Cover food", "Leave food open to flies"], ["Separate raw / cooked", "Use one board for all"], ["Use safe water", "Use dirty water"]]),
   "A table of four hygiene actions to do and to avoid.", "Table of do and do-not food hygiene rules."),
  [("Example 1", "Raw chicken was cut on a board. Then the same board was used for salad. What is wrong and what should be done?", ["Germs from raw chicken can pass to the salad (cross-contamination).", "Use separate boards or wash the board well with hot soapy water before using it for ready-to-eat food."], "Cross-contamination: separate boards or wash well"),
   ("Example 2", "Bacteria may double about every 20 minutes in warm conditions (an illustration). How many times larger is one group after 2 hours?", ["2 hours = 120 minutes = 6 periods of 20 minutes.", "Each period doubles: 2^6 = 64 times."], "About 64 times")],
  [M("Before cooking you should", "wash your hands with soap and clean water", ["rub them with oil", "do nothing", "wipe on your clothes"], "Hand washing."),
   M("Cross-contamination means", "germs passing from one food to another", ["cooking twice", "freezing food", "adding salt"], "Definition."),
   TF("Pan handles should stick out over the edge of the stove.", False, "Turn them inwards.")],
  [M("Which is the best way to store cooked food for a few hours in a hot kitchen?", "Covered and kept cool or in a fridge if available", ["Uncovered on the table", "Near the fire", "In the sun"], "Cover and keep cool."),
   O("Give four rules of personal hygiene for people who prepare food.", "Wash hands; wear clean clothes or an apron; tie long hair; keep nails short and clean; cover cuts; do not cough over food.", "1 mark each, 4 marks.")],
  P("At a school feeding programme in Kumba, cooks prepare rice and stew for 200 pupils.",
    [pm("Which action prevents food poisoning?", "Washing hands and cooking thoroughly", ["Leaving food open", "Using dirty plates", "Not washing vegetables"], "Hygiene."),
     pn("Bacteria double every 20 minutes (illustration). How many times larger after 1 hour?", 8, "3 periods: 2^3 = 8."),
     po("Suggest one rule for serving leftovers.", "Reheat thoroughly until very hot throughout and eat the same day, or throw away if unsure.", "1 mark.")]),
  [("Food poisoning is commonly caused by", "germs in food", ["vitamins", "fibre", "water only"], "Germs."),
   ("Flies can spread germs to food if food is", "left uncovered", ["covered", "in a closed container", "in a fridge"], "Cover food."),
   ("Raw and cooked foods should be kept", "separate", ["together", "in the same bowl", "on the same board"], "Separate."),
   ("Safe drinking water can be made by", "boiling or proper treatment", ["adding sugar", "adding oil", "leaving it in the sun uncovered"], "Boil or treat."),
   ("A spill on the kitchen floor should be", "cleaned up at once", ["ignored", "left overnight", "covered with paper"], "Safety.")],
  notes=[HEALTH, "20-minute doubling time is illustrative (it varies by organism and conditions). Safe-water treatment methods follow local health guidance."], minutes=20)

