REF = "Cameroon GCE Board — Ordinary Level Food Science and Nutrition syllabus — to be checked against the official text"
p = mkpack("gceol-food-science", "Food Science and Nutrition — GCE O Level", "Form 5", "GCE-OL", REF,
           "Nutrients, balanced diet, energy needs with calculations, digestion, cooking, hygiene, preservation and spoilage, deficiency diseases, additives, consumer education and budgeting, with a mock paper.")
c1 = p.chapter("nutrients", "Nutrients and diet", REF)

L1 = lesson(c1, "macronutrients", "Carbohydrates, fats and proteins",
  ["Classify carbohydrates as sugars and starch", "Describe functions and sources of fats and proteins", "Distinguish saturated and unsaturated fats in outline", "Name examples of complete and incomplete proteins in simple terms"],
  [("definition", "Carbohydrates", "**Carbohydrates** are made of carbon, hydrogen and oxygen. **Sugars** (glucose, sucrose, lactose) are sweet and dissolve in water; **starch** is in cassava, plantain, maize, rice and yams. Starch is digested to glucose, the body's main fuel. **Cellulose** is a carbohydrate in plant walls that humans cannot digest; it forms part of dietary fibre."),
   ("definition", "Fats and oils", "**Fats** (solid at room temperature) and **oils** (liquid) are made of **fatty acids** and **glycerol**. They give a concentrated source of energy, insulate and protect organs, and carry **vitamins A, D, E and K**. **Saturated** fats are mostly from animals (butter, fat on meat); **unsaturated** fats are mostly from plants and fish (groundnut oil, fish oil). Palm oil is a plant oil that has a fairly high saturated fat content; a little is enough."),
   ("definition", "Proteins", "**Proteins** are made of **amino acids**. They are needed for growth, repair of tissue, and for enzymes and hormones. Foods with all the **essential amino acids** in good amounts (eggs, milk, fish, meat) are called **first-class** (or complete); many plant proteins (beans, maize) are lower in one or more essential amino acids, but **mixing** them (for example beans with maize) improves the balance."),
   ("attention", "Be careful", "- Fat is not 'bad': the body needs some; too much, especially saturated fat, is a health concern.\n- Sugar gives energy but no other nutrients ('empty' energy).\n- Excess protein is used for energy or stored as fat; it is not 'saved' as muscle. " + HEALTH)],
  ("Food pyramid", pyramid("Eating pyramid (guide)", ["Fats, oils, sugar (little)", "Protein foods", "Fruit and vegetables", "Staple foods (largest)"]),
   "A pyramid with staple foods at the base, then fruit and vegetables, protein foods, and a small top for fats, oils and sugar.", "Food pyramid from staples at the bottom to fats, oils and sugar at the top."),
  [("Example 1 - Classify", "Classify: cassava, groundnut oil, beans, honey.", ["Cassava is rich in starch (carbohydrate); honey is mostly sugar (carbohydrate).", "Groundnut oil is a fat/oil; beans are a protein food."], "Starch, fat, protein, sugar"),
   ("Example 2 - Mixing proteins", "Why is beans eaten with maize better than either alone?", ["Maize and beans are each lower in some essential amino acids.", "Together they supply a better balance of amino acids."], "They complement each other")],
  [M("Starch is found in", "plantain and cassava", ["fish oil", "salt", "water"], "Starchy foods."),
   M("Fats carry the vitamins", "A, D, E and K", ["only C", "B and C only", "none"], "Fat-soluble vitamins."),
   TF("Cellulose is digested by humans.", False, "Humans cannot digest cellulose; it is fibre.")],
  [M("Which is a first-class protein food?", "Egg", ["Sugar", "Cassava", "Salt"], "Eggs contain all essential amino acids."),
   O("Explain what is meant by 'complementary proteins' and give an example.", "Plant proteins that are low in different essential amino acids can be eaten together so that the mixture is better balanced, for example beans with maize.", "1 mark meaning, 1 mark explanation, 1 mark example.")],
  P("A meal contains: boiled plantain (starchy), fried fish, a small amount of palm oil and green vegetables.",
    [pm("The main source of starch is", "plantain", ["fish", "palm oil", "vegetables"], "Plantain."),
     pm("The main source of protein is", "fish", ["plantain", "oil", "water"], "Fish."),
     po("Name the nutrient provided by the palm oil and one function.", "Fat (oil); a concentrated source of energy (or carrying fat-soluble vitamins).", "1 mark nutrient, 1 mark function.")]),
  [("Proteins are made of", "amino acids", ["fatty acids", "starch", "fibre"], "Amino acids."),
   ("Fats are made of", "fatty acids and glycerol", ["amino acids", "glucose only", "water"], "Fats."),
   ("A main function of carbohydrate is", "energy", ["making enzymes only", "insulating only", "digesting"], "Energy."),
   ("Sugar mostly gives", "energy only", ["all vitamins", "all minerals", "growth only"], "Empty energy."),
   ("Unsaturated fats are mostly from", "plants and fish", ["only butter", "only fat of meat", "only milk"], "General statement.")],
  notes=[HEALTH, "Palm oil: statement about saturated fat content is general; check local nutrition tables. 'Empty energy' is a textbook phrase."], minutes=25)

L2 = lesson(c1, "micronutrients", "Vitamins, minerals, water and fibre",
  ["Describe functions of vitamins A, B group, C, D and K in general terms", "Describe functions of calcium, iron, iodine, phosphorus and sodium", "Explain the importance of water and fibre", "Give Cameroonian food sources"],
  [("definition", "Vitamins", "**Fat-soluble** vitamins (A, D, E, K) are stored in the body; **water-soluble** vitamins (B group, C) are not stored in large amounts and are easily lost in cooking water. A: sight, skin and resistance to infection. B group: release of energy from food and healthy nerves. C: healing and healthy gums and blood vessels. D: absorption of calcium for bones. K: blood clotting."),
   ("definition", "Minerals", "**Calcium** and **phosphorus**: bones and teeth. **Iron**: part of haemoglobin in red blood cells. **Iodine**: thyroid hormones. **Sodium** and **potassium**: water balance and nerve function. **Fluoride**: strong teeth. Too much salt (sodium) is linked with high blood pressure, so use salt moderately."),
   ("retenir", "Sources", "A: red palm oil, dark green leaves, orange fruits, liver, eggs. B group: whole grains, beans, groundnuts, meat, fish. C: guava, orange, mango, pawpaw, tomatoes, fresh leaves. D: oily fish, eggs, and sunlight on skin. Iron: meat, fish, beans, green leaves. Calcium: milk, small fish with bones, green leaves. Iodine: fish and iodised salt."),
   ("retenir", "Water and fibre", "**Water** is a solvent, helps digestion, carries nutrients and wastes in blood and controls body temperature (sweating). **Dietary fibre** (cellulose in vegetables, fruits, whole grains, beans) adds bulk, helps peristalsis and prevents constipation."),
   ("pieges", "Be careful", "- Vitamin C is destroyed by long cooking and lost in the water.\n- Iron from plant foods is absorbed less well than iron from meat; vitamin C in the same meal helps.\n- Do not give supplements without health-worker advice. " + HEALTH)],
  ("Table", cols("Nutrient, function, source", ["Nutrient", "Function", "Source"], [["Iron", "Blood", "Beans, fish"], ["Calcium", "Bones", "Milk, small fish"], ["Vit C", "Healing", "Guava, orange"], ["Vit A", "Sight", "Palm oil, leaves"]], w=440, size=12),
   "A table giving the function and food sources of iron, calcium, vitamin C and vitamin A.", "Table of four nutrients with function and local food sources."),
  [("Example 1", "A girl has pale skin and tires easily. Which mineral may be low, and which foods help? (General information only.)", ["Pale skin and tiredness can be signs of a shortage of iron (anaemia); a health worker should check.", "Iron-rich foods: meat, fish, beans, green leaves, with a vitamin C source."], "Iron; a health worker should be consulted"),
   ("Example 2", "Why is it better to cook leafy vegetables briefly?", ["Vitamin C and some B vitamins are water-soluble and heat-sensitive.", "Brief cooking with little water loses fewer vitamins."], "Less vitamin loss")],
  [M("Which vitamin helps blood to clot?", "Vitamin K", ["Vitamin C", "Vitamin A", "Vitamin D"], "K."),
   M("Which mineral is part of haemoglobin?", "Iron", ["Calcium", "Sodium", "Iodine"], "Iron."),
   TF("Fibre is digested into glucose in the body.", False, "Fibre is not digested.")],
  [MT("Match the nutrient with its main function.", [("Calcium", "Bones and teeth"), ("Iodine", "Thyroid hormones"), ("Vitamin D", "Absorption of calcium"), ("Vitamin A", "Sight")], "Standard functions."),
   O("Explain why water is essential for the body. Give three functions.", "It acts as a solvent for chemical reactions; carries nutrients and waste in the blood; helps cool the body by sweating; helps digestion.", "1 mark each, 3.")],
  P("Mama Eto eats mostly cassava with little other food. A health worker advises adding beans, green leaves and fruit.",
    [pm("Beans mainly add", "protein and iron", ["only fat", "only sugar", "only salt"], "General."),
     pm("Green leaves add", "vitamins, minerals and fibre", ["only fat", "only starch", "nothing"], "General."),
     po("Why might a fruit rich in vitamin C help when eating beans?", "Vitamin C helps the body absorb iron from plant foods.", "1 mark each.")]),
  [("Water-soluble vitamins include", "C and B group", ["A and D", "K and E", "none"], "Water-soluble."),
   ("Vitamin D helps the body absorb", "calcium", ["iodine", "fibre", "sugar"], "D and calcium."),
   ("Too much salt is linked to", "high blood pressure", ["strong bones", "better sight", "no effect"], "General statement."),
   ("Fibre helps prevent", "constipation", ["thirst", "hunger", "sleep"], "Peristalsis."),
   ("Iodised salt is used to supply", "iodine", ["iron", "calcium", "vitamin C"], "Iodine.")],
  notes=[HEALTH], minutes=25)

L3 = lesson(c1, "balanced-diet", "Balanced diet and meal planning",
  ["Define a balanced diet and list factors that affect dietary needs", "Plan meals for different people using local foods", "Evaluate a menu", "Use the food groups"],
  [("definition", "Balanced diet", "A **balanced diet** supplies all nutrients, fibre and water in suitable amounts for the person. Needs vary with **age**, **sex**, **activity (occupation)**, **climate**, **health** and special conditions such as **pregnancy** and **breastfeeding**. Growing children need relatively more protein, calcium and iron for their size."),
   ("retenir", "Food groups", "Staples (cassava, plantain, maize, rice, yam, cocoyam, bread) for energy; legumes, nuts and animal foods (beans, groundnuts, fish, eggs, meat, milk) for protein; fruit and vegetables (eru, bitterleaf, huckleberry leaves, tomatoes, mango, pawpaw) for vitamins, minerals and fibre; oils (palm oil, groundnut oil) in small amounts."),
   ("methode", "Planning a day", "Include a staple, a protein food and a vegetable or fruit in the main meals; snacks from fruit or groundnuts; vary foods through the week; consider cost, season, cooking time and the family's tastes; use different colours. Check that the day is not too rich in fat, sugar or salt."),
   ("attention", "Be careful", "- 'Balanced' is judged over the day or week, not on one meal.\n- A pregnant or breastfeeding woman needs advice from a health worker.\n- Food taboos and beliefs should be respected while giving correct health information. " + HEALTH)],
  ("Menu bars", stackbar("Share of a day's menu (illustrative)", [("Staples", 45, "lightyellow"), ("Fruit, veg", 30, "lightgreen"), ("Protein", 20, "lightorange"), ("Oil, sugar", 5, "lightblue")], w=440, h=150),
   "A bar showing an illustrative day's menu: staples 45 percent, fruit and vegetables 30, protein foods 20, oil and sugar 5.", "Stacked bar of an illustrative menu: staples 45, fruit and vegetables 30, protein foods 20, oil and sugar 5 percent."),
  [("Example 1 - Evaluate a menu", "Menu for a day: breakfast: tea with sugar and bread; lunch: rice and fried plantain; supper: garri and sugar water. Comment on balance.", ["The menu is high in starch and sugar and low in protein, vegetables and fruit.", "Improve it: add eggs or beans, a vegetable sauce (eru, tomatoes), and fruit; reduce sugar."], "Unbalanced: add protein, vegetables and fruit"),
   ("Example 2 - Plan", "Plan a balanced supper for a growing child using local foods.", ["Staple: boiled plantain or cassava. Protein: fish or beans.", "Vegetable: green leaves (e.g. eru) with a little oil; fruit such as pawpaw."], "Plantain, fish, eru, pawpaw")],
  [M("A balanced diet depends on a person's", "age, sex and activity", ["shoe size", "hair colour", "name"], "Needs differ."),
   M("Fruit and vegetables mainly give", "vitamins, minerals and fibre", ["only starch", "only protein", "only fat"], "Protective foods."),
   TF("A single meal must contain every nutrient in exact proportions.", False, "Balance is judged over the day or week.")],
  [M("Which person is likely to need more energy?", "A farmer doing heavy work", ["A person resting in bed all day", "A sleeping baby", "A person sitting all day"], "Activity increases need."),
   O("Plan a balanced day's meals for a Form 5 student using local foods and say why it is balanced.", "Breakfast: pap with groundnuts and fruit. Lunch: rice, beans, vegetable sauce. Supper: boiled plantain with fish and green leaves. It has staples (energy), protein (beans, fish, groundnuts) and vegetables/fruit (vitamins, minerals, fibre).", "1 mark each meal with all groups; 1 mark explanation.")],
  P("Esther is 15 and active in sport. Her daily food: white bread and tea for breakfast, rice and stew for lunch, rice again for supper. She eats no fruit.",
    [pm("What is missing most?", "Vegetables and fruit, and enough protein variety", ["Starch", "Salt", "Water only"], "Repetitive starch diet."),
     pm("Which change would help?", "Add beans or eggs and a fruit", ["Remove all food", "Add sugar", "Add more rice"], "Protein, vitamins."),
     po("Suggest an inexpensive protein food.", "Beans or groundnuts.", "1 mark.")]),
  [("Staple foods are mainly", "energy foods", ["protein foods", "vitamin foods", "water"], "Staples."),
   ("Pregnant women should", "get advice from a health worker", ["avoid all food", "eat only sugar", "ignore diet"], "Safe advice."),
   ("Variety in the diet helps", "supply all nutrients", ["increase waste", "waste money", "cause deficiencies"], "Variety."),
   ("Which is a protein food?", "Beans", ["Cassava", "Sugar", "Palm oil"], "Legume."),
   ("A menu high in sugar and starch and low in other foods is", "unbalanced", ["balanced", "ideal", "healthy"], "Unbalanced.")],
  notes=[HEALTH, "Percentages in the figure are illustrative; do not present them as recommendations."], minutes=25)

L4 = lesson(c1, "energy", "Energy values and energy needs",
  ["State the energy values per gram used in this course", "Calculate the energy in a meal", "Compare energy intake with energy needs", "Convert kilojoules and kilocalories (approximately)"],
  [("definition", "Units and values", "Energy is measured in **kilojoules (kJ)** (and often in **kilocalories (kcal)**; 1 kcal is about 4.2 kJ). In this course we use: **carbohydrate 17 kJ/g, protein 17 kJ/g, fat 37 kJ/g** (about 4, 4 and 9 kcal/g). These are standard rounded values used in school; tables may differ slightly."),
   ("methode", "Energy of a meal", "Energy (kJ) = grams of carbohydrate x 17 + grams of protein x 17 + grams of fat x 37. Example: 60 g carbohydrate, 20 g protein and 10 g fat give 60 x 17 + 20 x 17 + 10 x 37 = 1020 + 340 + 370 = 1730 kJ. **Percentage of energy from fat** = (fat energy / total energy) x 100."),
   ("retenir", "Energy needs", "Energy needs depend on **age, sex, body size, activity and climate**. The **basal metabolic rate (BMR)** is the energy needed at rest for breathing, heartbeat, and keeping warm. Active people and growing children need more energy for their size. If intake is greater than use over a long time, the extra is stored as fat; if less, the body loses weight."),
   ("pieges", "Be careful", "- Fat has more than twice the energy per gram of carbohydrate or protein.\n- Water, vitamins, minerals and fibre have no useful energy value.\n- Do not use these calculations to diagnose or give personal advice; a dietitian must do that. " + HEALTH)],
  ("Energy bars", bars([("Carbohydrate", 17, "orange"), ("Protein", 17, "blue"), ("Fat", 37, "red")], unit="kJ per gram", w=400, h=240),
   "A bar chart: carbohydrate 17 kJ per gram, protein 17 and fat 37.", "Bar chart of energy values per gram: carbohydrate 17, protein 17 and fat 37 kilojoules."),
  [("Example 1 - Energy of a meal", "A meal of rice and stew contains 80 g carbohydrate, 15 g protein and 12 g fat (illustrative values). Find the energy.", ["Carbohydrate: 80 x 17 = 1360 kJ. Protein: 15 x 17 = 255 kJ. Fat: 12 x 37 = 444 kJ.", "Total = 1360 + 255 + 444 = 2059 kJ."], "2059 kJ"),
   ("Example 2 - Percentage from fat", "In the meal of 60 g carbohydrate, 20 g protein and 10 g fat (1730 kJ), what percentage of the energy comes from fat?", ["Fat energy = 10 x 37 = 370 kJ.", "(370 / 1730) x 100 = 21.4 %."], "About 21 %")],
  [N("Energy from 50 g of carbohydrate (17 kJ/g) in kJ", 850, "50 x 17 = 850."),
   N("Energy from 10 g of fat (37 kJ/g) in kJ", 370, "10 x 37 = 370."),
   M("Which nutrient gives the most energy per gram?", "Fat", ["Carbohydrate", "Protein", "Water"], "37 kJ/g.")],
  [N("A snack has 30 g carbohydrate, 5 g protein and 20 g fat. Energy in kJ", 1335, "30x17=510; 5x17=85; 20x37=740; total 1335."),
   O("Explain why a farmer needs more energy than an office worker of the same size.", "The farmer does heavy physical work, so more energy is used by the muscles; energy intake must match to avoid loss of weight and tiredness.", "1 mark each point (2) plus 1 for BMR/activity link.")],
  P("A lunch contains 70 g carbohydrate, 25 g protein and 15 g fat (illustrative).",
    [pn("Energy from carbohydrate (kJ)", 1190, "70 x 17 = 1190."),
     pn("Total energy (kJ)", 2170, "1190 + 25x17 (425) + 15x37 (555) = 2170."),
     pn("Fat's percentage of total energy (to the nearest whole number)", 26, "555 / 2170 = 25.6 per cent, about 26.", tol=1)]),
  [("The energy value of protein used here is", "17 kJ per gram", ["37 kJ per gram", "0 kJ per gram", "100 kJ per gram"], "Protein."),
   ("BMR is the energy needed", "at rest", ["during sport only", "only during sleep", "only in hot weather"], "Basal."),
   ("1 kcal is about", "4.2 kJ", ["42 kJ", "0.42 kJ", "420 kJ"], "Conversion."),
   ("If energy intake is much greater than energy use over a long time", "weight tends to increase", ["weight drops", "nothing happens", "bones grow"], "Stored fat."),
   ("Nutrients with no useful energy value include", "water and fibre", ["fat", "protein", "starch"], "No energy.")],
  notes=[HEALTH, "Energy values per gram (17, 17, 37 kJ/g) are rounded textbook values; the syllabus may use 16/16/37 or kcal values. Meal compositions in examples are illustrative, not real analyses."], minutes=30)
assert 80 * 17 + 15 * 17 + 12 * 37 == 2059 and 30 * 17 + 5 * 17 + 20 * 37 == 1335 and 70 * 17 + 25 * 17 + 15 * 37 == 2170 and round(555 / 2170 * 100) == 26

L5 = lesson(c1, "digestion", "Digestion and absorption",
  ["Describe the parts of the digestive system and their functions", "Describe the digestion of starch, protein and fat in outline", "Explain absorption", "Describe the role of enzymes"],
  [("definition", "Digestion", "**Digestion** breaks large food molecules into small soluble ones that can be absorbed into the blood. **Mechanical** digestion (chewing, churning) breaks food into pieces; **chemical** digestion uses **enzymes**. The path: mouth, oesophagus, stomach, small intestine, large intestine, rectum, anus. The liver, gall bladder and pancreas help."),
   ("retenir", "Where and how", "**Mouth**: chewing; amylase in saliva starts digesting starch. **Stomach**: churning, acid, protease (pepsin) starts protein digestion. **Small intestine**: bile (from liver) helps fat digestion; enzymes from the pancreas and the gut finish digestion of starch (to glucose), protein (to amino acids) and fat (to fatty acids and glycerol); **absorption** into the blood through villi. **Large intestine**: absorbs water."),
   ("methode", "Enzymes", "**Enzymes** are biological catalysts made of protein. Each works on a specific food: **amylase** on starch, **protease** on protein, **lipase** on fats. They work best at about body temperature and the right pH; they are destroyed by high temperatures."),
   ("pieges", "Be careful", "- Absorption mainly takes place in the **small** intestine, not the stomach.\n- Bile does not contain enzymes; it breaks fat into droplets (emulsifies).\n- Fibre is not digested but is needed. " + HEALTH)],
  ("Digestive path", flow("Path of food", ["Mouth: chewing, amylase", "Stomach: acid, protease", "Small intestine: digestion + absorption", "Large intestine: water absorbed"], colors=["lightyellow", "lightorange", "lightgreen", "lightblue"]),
   "Four boxes showing the path of food from mouth to large intestine and what happens in each.", "Flow of digestion: mouth, stomach, small intestine, large intestine."),
  [("Example 1 - End products", "What are the end products of digestion of starch, protein and fat?", ["Starch is digested to glucose; protein to amino acids.", "Fat to fatty acids and glycerol."], "Glucose; amino acids; fatty acids and glycerol"),
   ("Example 2 - Why chew?", "Why is chewing food well helpful?", ["Chewing breaks food into small pieces: a larger surface area for enzymes.", "Saliva (with amylase) mixes with the food."], "Larger surface area; saliva begins starch digestion")],
  [M("Starch digestion begins in the", "mouth", ["stomach", "large intestine", "liver"], "Saliva amylase."),
   M("Most absorption of food takes place in the", "small intestine", ["stomach", "mouth", "anus"], "Villi."),
   TF("Bile contains digestive enzymes.", False, "Bile emulsifies fat but has no enzymes.")],
  [MT("Match the enzyme to the food it digests.", [("Amylase", "Starch"), ("Protease", "Protein"), ("Lipase", "Fat"), ("None (not digested)", "Fibre")], "Enzymes are specific."),
   O("Describe how the small intestine is adapted for absorption.", "It is long, with a lining folded into many villi that give a large surface area; the villi have thin walls and a rich blood supply so digested food passes quickly into the blood.", "1 mark each of: long/large surface area, villi, thin wall, blood supply (3 marks).")],
  P("A student chews a piece of cooked cassava for several minutes and notices a slightly sweet taste.",
    [pm("Which enzyme is responsible?", "Amylase", ["Protease", "Lipase", "None"], "Saliva amylase starts breaking starch to sugar."),
     pm("The sweet taste is from", "sugar produced from starch", ["fat", "protein", "water"], "Maltose/sugar."),
     po("Why does the enzyme not work well if the food is very hot when swallowed?", "High temperature can destroy the enzyme (denature it) so it no longer works.", "1 mark.")]),
  [("Digestion makes food molecules", "small enough to be absorbed", ["bigger", "hotter", "colder"], "Absorption."),
   ("The stomach contains", "acid and protease", ["only water", "only bile", "only amylase"], "Stomach."),
   ("Villi are found in the", "small intestine", ["mouth", "stomach", "liver"], "Surface area."),
   ("The large intestine mainly absorbs", "water", ["fat", "protein", "vitamins A only"], "Water."),
   ("Enzymes are", "biological catalysts", ["vitamins", "minerals", "fibres"], "Catalysts.")],
  notes=[HEALTH, "Anatomical detail kept at O Level; check the diagram expectations for the paper."], minutes=25)

c2 = p.chapter("preparation", "Food preparation, safety and preservation", REF)
L6 = lesson(c2, "cooking-methods", "Cooking and food preparation",
  ["Explain why food is cooked", "Compare cooking methods and their effect on nutrients", "Describe changes to starch, protein and fat on heating", "Choose a suitable method"],
  [("definition", "Why we cook", "Cooking makes food **safe** (kills many germs), **palatable** (flavour, texture, appearance) and **easier to digest**. Methods using **water**: boiling, simmering, steaming, stewing. Methods using **fat**: frying (shallow and deep). Methods using **dry heat**: roasting, grilling, baking."),
   ("retenir", "Changes on heating", "**Starch** grains absorb water and burst (**gelatinisation**), thickening a sauce. **Proteins** **coagulate** (set) as an egg white turns solid; over-cooking makes them tough. **Fats** melt; very high heat makes oil smoke and break down. **Vitamin C** and some B vitamins are lost in cooking, mostly into the water."),
   ("methode", "Keeping nutrients", "Wash before cutting; do not soak; cook in a small amount of water for a short time; use the cooking water; do not add bicarbonate of soda (it destroys some vitamins); serve soon after cooking; fry in moderate amounts of fresh oil; avoid burning."),
   ("pieges", "Be careful", "- Deep-frying adds a lot of energy from fat.\n- Never leave hot oil unattended: fat fires need a lid, not water.\n- Cassava products must be prepared properly (peeling, soaking, fermenting, drying and cooking as traditionally done) to be safe. " + HEALTH)],
  ("Methods", cols("Methods of cooking", ["Medium", "Methods"], [["Water", "Boil, steam, stew"], ["Fat", "Fry"], ["Dry heat", "Roast, grill, bake"]]),
   "A table grouping cooking methods by water, fat and dry heat.", "Table of cooking methods by medium: water, fat and dry heat."),
  [("Example 1", "Why does a sauce thicken when flour or cornflour is heated in it?", ["Starch grains absorb water and swell.", "They burst and the starch forms a thick gel (gelatinisation)."], "Gelatinisation of starch"),
   ("Example 2", "Choose a method for each aim: (a) low fat, (b) crisp texture, (c) soft tender meat cooked slowly.", ["(a) Steaming or grilling adds little fat. (b) Frying or roasting gives crispness.", "(c) Stewing in liquid softens meat."], "(a) steaming/grilling, (b) frying/roasting, (c) stewing")],
  [M("Heating starch with water makes it", "swell and thicken", ["disappear", "become fat", "turn to protein"], "Gelatinisation."),
   M("Which method adds fat?", "Frying", ["Steaming", "Boiling", "Stewing without oil"], "Frying."),
   TF("Egg white coagulates when heated.", True, "Protein sets.")],
  [M("Which advice helps keep vitamin C in vegetables?", "Cook briefly in a small amount of water", ["Boil for a long time in a lot of water", "Add bicarbonate of soda", "Soak overnight before cooking"], "Reduce losses."),
   O("Explain what happens to protein when an egg is boiled.", "Heat denatures and coagulates the protein so the liquid white and yolk set into a solid.", "1 mark each of denature/coagulate and solid result (2) plus 1 for example.")],
  P("Mama Judith cooks eru with water leaf, fish and a little palm oil on a low fire for 20 minutes.",
    [pm("This method is called", "stewing", ["roasting", "deep-frying", "baking"], "Slow cooking in liquid."),
     pm("Which vitamins may be reduced?", "Heat-sensitive and water-soluble ones such as vitamin C", ["Calcium", "Fibre", "Iron only"], "General."),
     po("Suggest how to reduce vitamin loss.", "Cook for a shorter time, avoid too much water, serve soon.", "1 mark each.")]),
  [("Coagulation refers to", "protein setting on heating", ["starch dissolving", "water boiling", "fibre digesting"], "Protein."),
   ("Grilling uses", "dry heat", ["only water", "only steam", "cold"], "Grilling."),
   ("Cooking water from vegetables can be", "used in the sauce", ["always thrown away", "poured on the stove", "ignored"], "Vitamins."),
   ("Fat fires should be put out by", "covering with a lid or damp cloth, not with water", ["pouring water", "fanning", "adding oil"], "Safety."),
   ("Simmering is", "cooking just below boiling", ["frying", "baking", "grilling"], "Simmer.")],
  notes=[HEALTH, "Fire-safety advice must be confirmed by a trained instructor."], minutes=25)

L7 = lesson(c2, "hygiene-safety", "Food hygiene and kitchen safety",
  ["Explain how food becomes contaminated", "Describe personal, kitchen and food hygiene", "Describe safe storage temperatures in general terms", "Describe common kitchen accidents and prevention"],
  [("definition", "Contamination and food poisoning", "Food can be contaminated by **bacteria**, **viruses**, **moulds**, chemicals or physical objects. Sources: hands, raw meat and fish, flies and pests, dirty water, unwashed utensils, soil. **Food poisoning** may cause vomiting, diarrhoea and fever. Young children, the elderly and sick people are at greater risk."),
   ("retenir", "Bacteria and temperature", "Bacteria multiply fastest in warm, moist, protein-rich foods, roughly between 5 °C and 60 °C (the 'danger zone', flagged for review). They may double in number about every 20 minutes in good conditions (illustration only). Keep cold food cold (fridge below about 5 °C), hot food hot, and cook food until very hot all the way through (about 70 °C or more in the centre)."),
   ("methode", "Hygiene rules", "**Personal**: wash hands with soap, clean clothes or apron, tie hair back, cover cuts, do not cough over food. **Food**: buy fresh food, wash fruit and vegetables, separate raw and cooked, cover food, cool and store leftovers promptly. **Kitchen**: clean surfaces, wash cloths, dispose of waste, control flies and rats, safe water."),
   ("methode", "Kitchen safety", "Prevent burns (handles in, careful with hot oil), cuts (sharp knives used properly), electric shocks (dry hands, no damaged wires), slips (wipe spills), gas hazards (check cylinders and connections). Keep a first-aid kit and know basic first aid; learn from a trained person."),
   ("pieges", "Be careful", "- Food may look and smell normal and still be unsafe.\n- Leftovers should not be reheated many times.\n- Temperature values here are general; local food safety authorities give exact limits. " + HEALTH)],
  ("Bacteria growth", bars([("0 min", 1, "green"), ("20 min", 2, "green"), ("40 min", 4, "orange"), ("60 min", 8, "orange"), ("80 min", 16, "red")], unit="number of bacteria (illustration)", w=420, h=250),
   "A bar chart showing bacteria doubling every 20 minutes from 1 to 16 in 80 minutes.", "Bar chart: 1, 2, 4, 8 and 16 bacteria at 0, 20, 40, 60 and 80 minutes, an illustration of doubling."),
  [("Example 1 - Growth", "One bacterium doubles every 20 minutes in warm food (illustration). How many are there after 2 hours?", ["120 minutes / 20 = 6 doublings.", "2^6 = 64 bacteria."], "64"),
   ("Example 2 - Spot the faults", "A cook handles raw fish, wipes hands on her apron and chops salad on the same board. List the faults.", ["She did not wash her hands with soap after raw fish.", "Cross-contamination: raw fish board used for salad, and a dirty apron."], "No hand-wash; same board; dirty apron")],
  [N("Bacteria doubling every 20 minutes: how many after 1 hour from 1 bacterium?", 8, "2^3 = 8."),
   M("Food poisoning bacteria grow best in", "warm, moist, protein-rich food", ["dry flour", "dry rice stored in a sealed jar", "boiling water"], "Conditions."),
   TF("Raw and cooked foods should be stored together.", False, "Keep separate.")],
  [N("Starting with 5 bacteria that double every 20 minutes, how many after 80 minutes?", 80, "80 min = 4 doublings, 5 x 16 = 80."),
   O("Give four rules of kitchen hygiene.", "Clean surfaces; wash cloths; cover food; dispose of waste; control pests; use clean water.", "1 mark each, 4.")],
  P("A cook in Bafoussam prepared stew at 7 a.m. and left it covered on the table in the warm kitchen until 5 p.m., then served it.",
    [pm("What is the main risk?", "Bacteria multiplying while the food was warm", ["The stew became cold", "The vitamins increased", "The salt disappeared"], "Warm storage."),
     pn("From 1 bacterium doubling every 20 minutes, how many doublings happen in 2 hours?", 6, "120/20."),
     po("Suggest two ways to make the food safer.", "Cool and store it in a fridge or keep it very hot; reheat thoroughly; or cook only what is needed.", "1 mark each.")]),
  [("The 'danger zone' for bacterial growth is roughly", "5 to 60 degrees Celsius", ["-20 to 0", "100 to 200", "0 to 4"], "General value."),
   ("Cross-contamination is", "spread of germs from raw to cooked food", ["mixing two spices", "freezing", "adding salt"], "Spread."),
   ("To prevent burns, pan handles should be", "turned inwards", ["turned outwards", "removed", "heated"], "Safety."),
   ("Wiping spills prevents", "slips", ["hunger", "thirst", "weight gain"], "Safety."),
   ("A group at greater risk from food poisoning is", "young children", ["no one", "only athletes", "only cooks"], "Vulnerable.")],
  notes=[HEALTH, "Temperatures (5-60 degrees danger zone, about 70 degrees core temperature) are widely used guidance values; check national guidance. Doubling time 20 min is illustrative."], minutes=25)
assert 5 * 2 ** 4 == 80

L8 = lesson(c2, "spoilage-preservation", "Food spoilage and preservation",
  ["Explain causes of spoilage: microorganisms and enzymes", "Describe conditions for microbial growth", "Describe drying, smoking, salting, sugar, refrigeration, freezing and canning", "Give advantages and limitations"],
  [("definition", "Spoilage", "**Spoilage** is the process that makes food unfit to eat. Causes: **microorganisms** (bacteria, yeasts and moulds) and **enzymes** in the food itself (for example ripening and browning). Signs: bad smell, slime, mould, change of colour and taste, swelling of cans."),
   ("retenir", "Conditions for growth", "Microorganisms need **food**, **moisture**, **warmth**, **suitable pH** and (for many) **oxygen**, and time. Preservation works by removing, reducing or blocking one or more of these, or by killing the microorganisms."),
   ("retenir", "Methods", "**Drying/smoking** (dried fish, crayfish, smoked meat): removes water. **Salting and sugar**: draw out water. **Refrigeration** (about 0-5 °C) slows growth; **freezing** (about -18 °C) stops growth, but does not kill all germs. **Canning**: heat in sealed cans. **Pickling**: acid (vinegar). **Fermentation**: useful microorganisms make acid (e.g. yoghurt, fermented cassava products)."),
   ("pieges", "Be careful", "- Freezing does not kill all bacteria; they can grow again after thawing.\n- Do not refreeze thawed food.\n- Moulds on groundnuts and maize can produce toxins (aflatoxins); dry well and store properly; discard mouldy or shrivelled nuts.\n- " + HEALTH)],
  ("Methods table", cols("Preservation", ["Method", "Principle"], [["Drying", "Removes water"], ["Refrigeration", "Cold slows growth"], ["Canning", "Heat + seal"], ["Salting", "Draws out water"]]),
   "A table of four preservation methods with the principle behind each.", "Table: drying removes water, refrigeration uses cold, canning uses heat and sealing, salting draws out water."),
  [("Example 1 - Principle", "Explain why smoked and dried fish keeps for longer than fresh fish.", ["Microorganisms need moisture to grow.", "Drying and smoking remove most of the water, so growth is stopped."], "Little water: no microbial growth"),
   ("Example 2 - Choose", "A farmer in Bamenda has a large harvest of groundnuts. How can he store them safely?", ["Dry them well in the sun on a clean surface.", "Store in clean, dry, ventilated containers off the ground; check for mould and discard bad nuts."], "Dry well; store dry; sort")],
  [M("Spoilage is caused by", "microorganisms and enzymes", ["only vitamins", "only salt", "only water"], "Two main causes."),
   M("Freezing", "stops growth but does not kill all bacteria", ["kills all germs", "makes food sterile", "adds water"], "Freezing."),
   TF("Microorganisms need moisture to grow.", True, "Yes.")],
  [M("Canning preserves food by", "killing microorganisms with heat and sealing out air", ["adding water", "adding bacteria", "drying only"], "Canning."),
   O("Explain why salt can preserve fish.", "Salt draws water out of the fish and of microorganisms by osmosis, so they cannot grow.", "1 mark each of water removed, microbes cannot grow, link to salt.")],
  P("A grocer in Limbe sells fresh fish, smoked fish and canned sardines.",
    [pm("Which has had most water removed?", "Smoked fish", ["Fresh fish", "Canned sardines in oil", "None"], "Drying/smoking."),
     pm("Which relies on heating and sealing?", "Canned sardines", ["Smoked fish", "Fresh fish", "Dried pepper"], "Canning."),
     po("State one sign that a can should not be used.", "A swollen, leaking or badly dented can.", "1 mark.")]),
  [("Mould is a kind of", "microorganism", ["vitamin", "mineral", "fibre"], "Fungus."),
   ("Pickling uses", "acid", ["sugar only", "oil only", "light"], "Vinegar."),
   ("A refrigerator", "slows microbial growth", ["stops all", "kills all", "adds salt"], "Cold."),
   ("Thawed food should", "not be refrozen", ["be refrozen at once", "be left for days", "be dried"], "Safety."),
   ("Moulds on groundnuts can produce", "harmful toxins", ["vitamins", "extra protein", "nothing"], "Aflatoxins.")],
  notes=[HEALTH, "Temperatures (0-5 degrees, -18 degrees) are standard guidance values. Aflatoxin comment is a general food-safety statement."], minutes=25)

c3 = p.chapter("health", "Diet, health and the consumer", REF)
L9 = lesson(c3, "malnutrition-deficiency", "Malnutrition and deficiency diseases",
  ["Define malnutrition (undernutrition and overnutrition)", "Describe protein-energy malnutrition in outline", "Name common deficiency diseases, causes and prevention", "Describe obesity and diet-related risks in outline"],
  [("definition", "Malnutrition", "**Malnutrition** means a poor state of nutrition: **undernutrition** (too little food or too few nutrients) or **overnutrition** (too much food, leading to overweight). Causes include poverty, poor food choices, infections, lack of knowledge, famine and some illnesses. Children, pregnant women and the elderly are especially vulnerable."),
   ("definition", "Protein-energy malnutrition", "In children, a lack of protein and energy can cause **marasmus** (severe wasting, very thin) or **kwashiorkor** (swollen feet and belly, changes in hair and skin). These need **medical treatment**. Prevention: enough varied food, breastfeeding for infants, good weaning foods and prevention and treatment of infections."),
   ("retenir", "Deficiency diseases", "**Vitamin A**: poor sight in dim light, infections. **Vitamin C**: scurvy (bleeding gums, slow healing). **Vitamin D** (and calcium): rickets (soft bones) in children. **Iron**: anaemia (tiredness, pale). **Iodine**: goitre (swollen neck). **Vitamin B1 (thiamine)**: beriberi. **Niacin**: pellagra. Prevention: a varied diet, fortified foods and supplements where recommended by health services."),
   ("retenir", "Overnutrition", "Eating more energy than the body uses, with little exercise, can lead to **obesity**, which increases the risk of conditions such as high blood pressure and diabetes. Healthy habits: balanced diet, less sugar, fat and salt, more fruit and vegetables, regular physical activity."),
   ("pieges", "Be careful", "- Diagnosis and treatment belong to health workers, not to a textbook.\n- Not every swollen belly is kwashiorkor.\n- Supplements are not a substitute for food.\n- " + HEALTH)],
  ("Table", cols("Deficiency and disease", ["Lacking", "Disease"], [["Vitamin C", "Scurvy"], ["Vitamin D", "Rickets"], ["Iron", "Anaemia"], ["Iodine", "Goitre"]]),
   "A table pairing four nutrient deficiencies with their diseases.", "Table: vitamin C scurvy, vitamin D rickets, iron anaemia, iodine goitre."),
  [("Example 1", "Which nutrient shortage is linked to goitre, and what is a simple prevention?", ["Goitre is linked to a shortage of iodine.", "Use iodised salt and eat fish; follow health-service advice."], "Iodine; iodised salt"),
   ("Example 2", "A health worker sees a very thin child with little muscle. Which condition could this be, and who should treat it?", ["Severe wasting from lack of food energy and protein suggests marasmus.", "It must be treated by trained health workers."], "Marasmus; medical treatment")],
  [M("Scurvy is caused by lack of", "vitamin C", ["iron", "vitamin D", "iodine"], "Scurvy."),
   M("Rickets in children is linked to lack of", "vitamin D and calcium", ["vitamin C", "protein only", "fibre"], "Soft bones."),
   TF("Kwashiorkor needs medical treatment.", True, "Yes.")],
  [MT("Match the condition with its main nutrient cause.", [("Anaemia", "Iron"), ("Goitre", "Iodine"), ("Scurvy", "Vitamin C"), ("Night blindness", "Vitamin A")], "General links."),
   O("Explain how the diet of a child can be improved to prevent protein-energy malnutrition.", "Give enough energy foods (staples), protein foods (beans, groundnuts, fish, eggs, milk), add oil for energy, continue breastfeeding for infants, give regular meals and seek health care for illness.", "1 mark each of: energy, protein, breastfeeding/weaning, health care (up to 3).")],
  P("A health talk in a village explains: obesity, anaemia, goitre and scurvy.",
    [pm("Which is a form of overnutrition?", "Obesity", ["Anaemia", "Goitre", "Scurvy"], "Excess energy."),
     pm("Which is linked to iron?", "Anaemia", ["Goitre", "Scurvy", "Rickets"], "Iron."),
     po("Suggest two healthy habits to prevent obesity.", "Eat less sugar and fat, eat more fruit and vegetables, be physically active.", "1 mark each.")]),
  [("Undernutrition means", "too little food or nutrients", ["too much food", "no water", "high fibre only"], "Definition."),
   ("Goitre is a swelling in the", "neck", ["leg", "foot", "hand"], "Thyroid."),
   ("Anaemia is linked to", "iron lack", ["vitamin C only", "sugar", "fat"], "Iron."),
   ("A child with possible severe malnutrition should see", "a health worker", ["nobody", "a friend only", "a hairdresser"], "Medical help."),
   ("Obesity increases the risk of", "high blood pressure", ["strong bones only", "better sight", "no risk"], "General statement.")],
  notes=[HEALTH, "Disease descriptions are deliberately brief and non-diagnostic; a dietitian or doctor should review wording, especially for kwashiorkor/marasmus."], minutes=25)

L10 = lesson(c3, "additives-consumer", "Food additives, labels and consumer education",
  ["Name types of food additive and their purposes", "Read a food label", "Compare value for money using unit prices", "State consumer rights and good buying habits"],
  [("definition", "Additives", "**Food additives** are substances added to food for a purpose: **preservatives** (keep food longer), **antioxidants** (stop fats going rancid), **colourings**, **flavourings** and **flavour enhancers**, **sweeteners**, **emulsifiers and stabilisers** (keep oil and water mixed or the texture steady) and **thickeners**. Approved additives are controlled by law; some people are sensitive to certain additives."),
   ("retenir", "Labels", "A food label usually shows the **name** of the food, the **ingredients** (listed from the largest amount to the smallest), the **net weight**, **nutrition information** (if provided), the **date mark** (best before / use by or expiry), the **producer or importer**, and storage instructions. 'Best before' is about quality; 'use by' / 'expiry' is about safety."),
   ("methode", "Unit price", "To compare prices, find the price per unit of weight: price / quantity. Example: 5 kg of rice for 3500 FCFA costs 700 FCFA per kg; 1 kg for 800 FCFA costs 800 FCFA per kg, so the large pack is cheaper per kg (if the family can use it before it spoils)."),
   ("retenir", "Consumer", "A good consumer reads labels, checks dates and packaging, compares prices, buys from clean sellers and keeps receipts. Consumers have rights to safe products, true information and fair treatment, and may complain to the seller or the competent consumer-protection authority."),
   ("pieges", "Be careful", "- Never buy cans that are swollen, leaking or badly dented.\n- A cheaper price per kg is not a saving if food is wasted.\n- Colours and flavours do not show nutritional value.\n- " + HEALTH)],
  ("Label", shapes([T(210, 20, "A food label (example)", 15, bold=True), RECT(80, 36, 260, 140, fill="white", stroke="ink", width=2),
     T(210, 58, "Groundnut paste", 14, bold=True), T(210, 80, "Ingredients: groundnuts, salt", 12), T(210, 100, "Net weight: 500 g", 12), T(210, 120, "Best before: see lid", 12), T(210, 142, "Store in a cool, dry place", 12), T(210, 164, "Packed in Cameroon", 12)], 420, 190),
   "An example food label with name, ingredients, net weight, date mark, storage and place of packing.", "Example label of groundnut paste showing the name, ingredients, weight, date mark, storage advice and origin."),
  [("Example 1 - Unit price", "Cooking oil: 1 litre costs 1500 FCFA; 5 litres cost 6500 FCFA. Which is cheaper per litre?", ["5 litres: 6500 / 5 = 1300 FCFA per litre.", "1 litre: 1500 FCFA per litre, so the 5-litre can is cheaper per litre."], "The 5-litre can (1300 FCFA per litre)"),
   ("Example 2 - Label", "A label lists: sugar, water, flavouring, colour. Which ingredient is present in the largest amount?", ["Ingredients are listed in order from largest to smallest amount.", "The first one listed, sugar."], "Sugar")],
  [M("Antioxidants in food are added to", "stop fats going rancid", ["add colour", "add protein", "make food hot"], "Purpose."),
   N("Unit price: 4 kg of rice costs 3200 FCFA. Price per kg", 800, "3200 / 4 = 800."),
   TF("Ingredients are listed from the smallest to the largest amount.", False, "From the largest to the smallest.")],
  [M("Which date mark is mainly about safety?", "Use by / expiry date", ["Best before", "Packed on a Monday", "Weight"], "Safety."),
   O("Give four pieces of information normally found on a food label.", "Name of food; ingredients; net weight; date mark; producer; storage instructions; nutrition information.", "1 mark each, 4.")],
  P("A shopper compares two packs of sugar: 1 kg for 700 FCFA and 3 kg for 1950 FCFA.",
    [pn("Price per kg of the 3 kg pack", 650, "1950 / 3 = 650."),
     pn("Saving per kg compared with the 1 kg pack", 50, "700 - 650 = 50."),
     po("State one reason why the larger pack might not be the best choice for every family.", "The family may not use it before it spoils or may not afford the larger payment at one time.", "1 mark.")]),
  [("Emulsifiers help", "oil and water stay mixed", ["colour food", "kill germs", "add vitamins"], "Emulsifier."),
   ("A net weight shows", "the weight of the food without packaging", ["the cost", "the producer", "the date"], "Net."),
   ("A swollen can should", "not be bought or used", ["be heated and eaten", "be given to children", "be stored"], "Safety."),
   ("Unit price helps to", "compare value for money", ["increase the weight", "colour food", "preserve food"], "Unit price."),
   ("A consumer has the right to", "safe products and true information", ["free food always", "nothing", "only advertising"], "Rights.")],
  notes=[HEALTH, "Consumer-protection institutions and legal references for Cameroon are not cited; add names after review."], minutes=25)
assert 6500 / 5 == 1300 and 1950 / 3 == 650 and 3200 / 4 == 800 and 3500 / 5 == 700

L11 = lesson(c3, "budgeting-meal-costs", "Budgeting and meal costing",
  ["Plan a food budget", "Calculate the cost of meals and of a week's food", "Suggest ways to save money without lowering nutrition", "Explain the effect of seasonal buying"],
  [("definition", "Food budget", "A **budget** is a plan for spending a limited income. Food is often the largest part of a household budget. Steps: list the family's income, decide how much goes to food, plan meals, make a shopping list, buy, and record spending."),
   ("methode", "Costing a meal", "Add the cost of each ingredient used (cost of the part used, not the whole pack). Cost per person = total cost / number of people. Example: for 5 people the ingredients cost 2250 FCFA, so each portion costs 2250 / 5 = 450 FCFA."),
   ("retenir", "Saving money", "Buy staples and vegetables **in season** and from local markets; compare prices; buy beans, groundnuts and eggs as cheaper proteins; avoid waste (cook the right amount, use leftovers safely); grow vegetables if possible; avoid expensive packaged snacks and soft drinks; plan before shopping."),
   ("pieges", "Be careful", "- The cheapest food is not always the best value; nutrition matters.\n- Buying much more than you can store leads to waste and spoilage.\n- Prices in examples are illustrative, not current market prices.")],
  ("Budget bars", bars([("Staples", 1200, "orange"), ("Protein", 900, "red"), ("Vegetables", 500, "green"), ("Oil, spice", 300, "blue")], unit="FCFA", w=420, h=250),
   "A bar chart of an illustrative meal cost: staples 1200 FCFA, protein 900, vegetables 500, oil and spices 300.", "Bar chart of illustrative meal costs in FCFA: staples 1200, protein 900, vegetables 500, oil and spices 300."),
  [("Example 1 - Cost per person", "Ingredients for a meal for 5 people (illustrative): staples 1200, protein 900, vegetables 500, oil and spices 300 FCFA. Find the total and the cost per person.", ["Total = 1200 + 900 + 500 + 300 = 2900 FCFA.", "Per person = 2900 / 5 = 580 FCFA."], "2900 FCFA; 580 FCFA each"),
   ("Example 2 - Weekly budget", "A family can spend 12 000 FCFA a week on food. They have spent 7 500 FCFA on staples and protein. How much is left for vegetables, fruit and oil? What fraction (as a percentage) is already spent?", ["Left = 12000 - 7500 = 4500 FCFA.", "Spent = 7500 / 12000 x 100 = 62.5 %."], "4500 FCFA left; 62.5 % spent")],
  [N("Cost of a meal: rice 800, fish 1200, vegetables 400 FCFA. Total", 2400, "800 + 1200 + 400 = 2400."),
   N("A meal costs 2400 FCFA for 6 people. Cost per person", 400, "2400 / 6 = 400."),
   TF("Buying foods in season is usually cheaper.", True, "Greater supply lowers prices.")],
  [N("A budget of 15 000 FCFA is used as: staples 6 000, protein 5 000, vegetables and fruit 2 500, other 1 500. What percentage is spent on protein?", 33.3, "5000/15000 x 100 = 33.3 %.", tol=0.1),
   O("Suggest four ways a family on a low income can eat well and save money.", "Buy seasonal foods; use beans, groundnuts and eggs for protein; plan meals and shop with a list; avoid waste; grow vegetables; avoid expensive snacks.", "1 mark each, 4.")],
  P("The Njoh family (6 people) has 18 000 FCFA a week for food. Plan: staples 7 200, protein 5 400, vegetables and fruit 3 600, oil and spices 1 800 FCFA (illustrative).",
    [pn("Total of the plan", 18000, "7200 + 5400 + 3600 + 1800 = 18000."),
     pn("Cost per person per week", 3000, "18000 / 6 = 3000."),
     pn("Percentage of the budget spent on vegetables and fruit", 20, "3600 / 18000 x 100 = 20 %.")]),
  [("A budget is", "a plan for spending income", ["a kind of food", "a recipe", "a tax"], "Budget."),
   ("Cost per person is", "total cost divided by number of people", ["total cost times people", "price of one item", "none"], "Division."),
   ("Cheaper protein foods include", "beans and groundnuts", ["only imported meat", "only sweets", "only drinks"], "Low-cost proteins."),
   ("Planning meals helps to", "avoid waste", ["increase waste", "buy more snacks", "skip nutrients"], "Planning."),
   ("Vegetables bought in season are", "usually cheaper", ["always more expensive", "never available", "not nutritious"], "Seasonality.")],
  notes=[HEALTH, "All prices are invented for practice; replace with current local prices after review."], minutes=25)
assert 1200 + 900 + 500 + 300 == 2900 and 2900 / 5 == 580 and 12000 - 7500 == 4500 and 7500 / 12000 * 100 == 62.5 and round(5000 / 15000 * 100, 1) == 33.3
assert 7200 + 5400 + 3600 + 1800 == 18000 and 3600 / 18000 * 100 == 20

mock(p, "1", "GCE O Level mock — Food Science and Nutrition", 90,
  "Answer all questions. The paper is marked out of 20. This is an original practice paper; its format is to be checked against the official texts of the Cameroon GCE Board. Energy values: carbohydrate 17 kJ/g, protein 17 kJ/g, fat 37 kJ/g.",
  [("Section A - Short questions (6 marks)", [
      (L1, M("Which nutrient is needed mainly for growth and repair?", "Protein", ["Carbohydrate", "Fibre", "Water"], "Protein.", points=1)),
      (L2, M("Lack of iodine is linked to", "goitre", ["scurvy", "rickets", "anaemia"], "Goitre.", points=1)),
      (L4, N("The energy in 20 g of fat (kJ)", 740, "20 x 37 = 740.", points=1)),
      (L5, M("Where does most absorption of digested food take place?", "Small intestine", ["Stomach", "Mouth", "Large intestine"], "Villi.", points=1)),
      (L7, TF("Raw meat and cooked food should be stored together.", False, "Keep them separate.", points=1)),
      (L8, M("Drying preserves food by", "removing water", ["adding water", "adding fat", "cooling it"], "Microbes need water.", points=1))]),
   ("Section B - Structured questions (10 marks)", [
      (L4, P("A meal contains 80 g carbohydrate, 20 g protein and 15 g fat (illustrative).",
         [pn("Energy from carbohydrate (kJ)", 1360, "80 x 17.", pts=1), pn("Total energy (kJ)", 2255, "1360 + 20 x 17 (340) + 15 x 37 (555) = 2255.", pts=2),
          pn("Percentage of energy from fat (nearest whole number)", 25, "555 / 2255 = 24.6, about 25 per cent.", tol=1, pts=2)])),
      (L10, P("Rice: 1 kg costs 800 FCFA, a 5 kg bag costs 3 500 FCFA.",
         [pn("Price per kg of the 5 kg bag", 700, "3500 / 5.", pts=2), pn("Saving per kg compared with buying 1 kg", 100, "800 - 700.", pts=1),
          po("Give one reason a family might still buy 1 kg.", "They may not afford the larger payment or may not be able to store rice safely.", "1 mark each of two reasons.", pts=2)]))]),
   ("Section C - Essay (4 marks)", [
      (L3, O("Plan a balanced day's menu for a Form 5 student using local foods and explain why it is balanced.", "Breakfast: pap with groundnuts and a fruit. Lunch: rice and beans with a vegetable sauce. Supper: boiled plantain with fish and green leaves. It supplies energy (staples), protein (beans, groundnuts, fish) and vitamins, minerals and fibre (vegetables, fruit).", "1 mark each for three suitable meals using food groups; 1 mark for explanation (4 marks).", points=4))])])
assert 80 * 17 + 20 * 17 + 15 * 37 == 2255 and round(555 / 2255 * 100) == 25 and 20 * 37 == 740
write(p)
